"use client";

import {
  animate,
  type MotionValue,
  type Transition,
  useMotionValue,
  useMotionValueEvent,
} from "motion/react";
import {
  type ReactNode,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
} from "react";

const useIsoLayoutEffect =
  typeof window === "undefined" ? useEffect : useLayoutEffect;

/**
 * Default sweep: a critically damped spring (no bounce). It decelerates into
 * the value like a real dial settling, and keeps its velocity when the value
 * changes mid-flight instead of restarting.
 */
export const DEFAULT_GAUGE_SWEEP_TRANSITION: Transition = {
  type: "spring",
  visualDuration: 0.9,
  bounce: 0,
};

/** Track + ruler fade in before the fill starts sweeping. */
export const GAUGE_TRACK_ENTER_TRANSITION: Transition = {
  duration: 0.45,
  ease: [0.23, 1, 0.32, 1],
};

export const clamp01 = (v: number) => Math.min(1, Math.max(0, v));

/**
 * Animates a motion value toward `target`. Starts from 0 on mount (after
 * `enterDelay`), then follows later target changes from wherever it is.
 * Runs entirely off React state — subscribers write to the DOM directly.
 */
export function useGaugeSweep({
  target,
  transition,
  enterDelay,
  instant,
}: {
  target: number;
  transition: Transition;
  enterDelay: number;
  instant: boolean;
}): MotionValue<number> {
  const progress = useMotionValue(instant ? target : 0);
  const enteredRef = useRef(false);
  const transitionKey = JSON.stringify(transition);

  useEffect(() => {
    if (instant) {
      progress.jump(target);
      enteredRef.current = true;
      return;
    }
    const delay = enteredRef.current ? 0 : enterDelay;
    enteredRef.current = true;
    const controls = animate(progress, target, { ...transition, delay });
    return () => controls.stop();
  }, [target, instant, transitionKey, enterDelay, progress]);

  return progress;
}

/** Subscribe to a motion value and run `apply` on mount + every change. */
export function useMotionValueApply(
  value: MotionValue<number>,
  apply: (v: number) => void
) {
  const applyRef = useRef(apply);
  applyRef.current = apply;
  useIsoLayoutEffect(() => {
    applyRef.current(value.get());
  });
  useMotionValueEvent(value, "change", (v) => applyRef.current(v));
}

/* -------------------------------------------------------------------------- */
/*                                   Ruler                                    */
/* -------------------------------------------------------------------------- */

export type GaugeRulerPosition = "inside" | "outside";

export interface GaugeRulerLabelOptions {
  /** `"majors"` labels every major tick; `"ends"` only the first and last */
  show?: "majors" | "ends";
  /** Domain the labels count across. Default 0 → 100 */
  min?: number;
  max?: number;
  format?: (value: number) => string;
  /** Default `var(--foreground)` at 72% opacity */
  color?: string;
}

export interface GaugeRulerOptions {
  /** `inside` (default) sits within the track; `outside` rings it */
  position?: GaugeRulerPosition;
  /** Number of intervals along the sweep (ticks = intervals + 1). Default 50 */
  ticks?: number;
  /** Every Nth tick is a major tick. Default 5 */
  majorEvery?: number;
  /** Tick colour. Default `var(--foreground)` */
  color?: string;
  /** Major tick length as a fraction of gauge size. Default 0.05 */
  majorLength?: number;
  /** Minor tick length as a fraction of gauge size. Default 0.028 */
  minorLength?: number;
  /** Gap between track and ruler as a fraction of gauge size. Default 0.028 */
  gap?: number;
  /** Brighten ticks up to the current value. Default true */
  highlightActive?: boolean;
  /** Numeric labels beside the major ticks */
  labels?: boolean | "majors" | "ends" | GaugeRulerLabelOptions;
}

const RULER_OPACITY = {
  majorLit: 0.95,
  majorDim: 0.32,
  minorLit: 0.55,
  minorDim: 0.16,
} as const;

export function resolveRulerLabels(
  labels: GaugeRulerOptions["labels"]
): GaugeRulerLabelOptions | null {
  if (!labels) {
    return null;
  }
  if (labels === true) {
    return { show: "majors" };
  }
  if (typeof labels === "string") {
    return { show: labels };
  }
  return labels;
}

export function rulerFontSize(size: number) {
  return Math.max(9, size * 0.034);
}

/** Radial space an outside ruler occupies beyond the track (px). */
export function rulerOutsideExtent(options: GaugeRulerOptions, size: number) {
  const { majorLength = 0.05, gap = 0.028 } = options;
  const labels = resolveRulerLabels(options.labels);
  return size * (gap + majorLength) + (labels ? rulerFontSize(size) * 1.8 : 0);
}

export function GaugeRuler({
  cx,
  cy,
  size,
  anchorRadius,
  startAngle,
  endAngle,
  progress,
  options,
}: {
  cx: number;
  cy: number;
  size: number;
  /** Track edge the ruler hangs from (inner edge for inside, outer for outside) */
  anchorRadius: number;
  startAngle: number;
  endAngle: number;
  progress: MotionValue<number>;
  options: GaugeRulerOptions;
}) {
  const {
    position = "inside",
    ticks = 50,
    majorEvery = 5,
    color = "var(--foreground)",
    majorLength = 0.05,
    minorLength = 0.028,
    gap = 0.028,
    highlightActive = true,
  } = options;
  const labels = resolveRulerLabels(options.labels);
  const intervals = Math.max(1, Math.round(ticks));
  const every = Math.max(1, Math.round(majorEvery));
  const dir = position === "outside" ? 1 : -1;
  const rStart = anchorRadius + dir * size * gap;
  const refs = useRef<(SVGLineElement | null)[]>([]);

  useMotionValueApply(progress, (p) => {
    for (let j = 0; j <= intervals; j++) {
      const el = refs.current[j];
      if (!el) {
        continue;
      }
      const major = j % every === 0;
      const dim = major ? RULER_OPACITY.majorDim : RULER_OPACITY.minorDim;
      const lit = major ? RULER_OPACITY.majorLit : RULER_OPACITY.minorLit;
      // Ramp over half an interval so ticks light as the fill reaches them.
      const t = highlightActive
        ? clamp01((p - j / intervals) * intervals * 2 + 1)
        : 0;
      el.setAttribute("stroke-opacity", String(dim + (lit - dim) * t));
    }
  });

  const sweep = endAngle - startAngle;
  const fontSize = rulerFontSize(size);
  const labelRadius =
    rStart + dir * (size * majorLength + fontSize * (dir > 0 ? 1 : 1.1));
  const min = labels?.min ?? 0;
  const max = labels?.max ?? 100;
  const format =
    labels?.format ?? ((v: number) => String(Math.round(v * 100) / 100));

  return (
    <g>
      {Array.from({ length: intervals + 1 }, (_, j) => {
        const major = j % every === 0;
        const rad = ((startAngle + (j / intervals) * sweep) * Math.PI) / 180;
        const len = size * (major ? majorLength : minorLength);
        const cos = Math.cos(rad);
        const sin = Math.sin(rad);
        return (
          <line
            key={j}
            ref={(el) => {
              refs.current[j] = el;
            }}
            stroke={color}
            strokeLinecap="round"
            strokeOpacity={
              major ? RULER_OPACITY.majorDim : RULER_OPACITY.minorDim
            }
            strokeWidth={major ? 1.75 : 1}
            x1={cx + cos * rStart}
            x2={cx + cos * (rStart + dir * len)}
            y1={cy + sin * rStart}
            y2={cy + sin * (rStart + dir * len)}
          />
        );
      })}
      {labels
        ? Array.from({ length: intervals + 1 }, (_, j) => {
            const isEnd = j === 0 || j === intervals;
            const show =
              labels.show === "ends" ? isEnd : j % every === 0 || isEnd;
            if (!show) {
              return null;
            }
            const t = j / intervals;
            const rad = ((startAngle + t * sweep) * Math.PI) / 180;
            return (
              <text
                dominantBaseline="central"
                fill={labels.color ?? "var(--foreground)"}
                fillOpacity={labels.color ? 1 : 0.72}
                fontSize={fontSize}
                key={`label-${j}`}
                style={{ fontVariantNumeric: "tabular-nums" }}
                textAnchor="middle"
                x={cx + Math.cos(rad) * labelRadius}
                y={cy + Math.sin(rad) * labelRadius}
              >
                {format(min + t * (max - min))}
              </text>
            );
          })
        : null}
    </g>
  );
}

/* -------------------------------------------------------------------------- */
/*                                   Needle                                   */
/* -------------------------------------------------------------------------- */

export type GaugeNeedleVariant = "line" | "gradient" | "triangle" | "polygon";

export interface GaugeNeedleOptions {
  /**
   * `line` — solid rounded stroke · `gradient` — stroke that fades in toward
   * the tip · `triangle` — slim acute triangle · `polygon` — slender diamond.
   * Default `gradient`.
   */
  variant?: GaugeNeedleVariant;
  /** Default `var(--foreground)` */
  color?: string;
  /** Stroke width (line / gradient) or base width (triangle / polygon) in px */
  width?: number;
  /**
   * Needle length as a fraction of its reach (center → tip). `1` runs from
   * the pivot; shorter values float the needle clear of the center label.
   */
  length?: number;
  /** Draw a pivot cap at the center (best with `length` near 1). */
  pivot?: boolean;
  /**
   * Where the tip lands: just inside the track (`inner`, default), the
   * track's outer edge (`outer`), or past the outermost layer (`edge`).
   */
  tip?: "inner" | "outer" | "edge";
}

const NEEDLE_DEFAULT_WIDTH: Record<GaugeNeedleVariant, number> = {
  line: 2.5,
  gradient: 4,
  triangle: 10,
  polygon: 8,
};

export function resolveNeedleOptions(
  needle: boolean | GaugeNeedleVariant | GaugeNeedleOptions | undefined
): GaugeNeedleOptions | null {
  if (!needle) {
    return null;
  }
  if (needle === true) {
    return {};
  }
  if (typeof needle === "string") {
    return { variant: needle };
  }
  return needle;
}

export function resolveRulerOptions(
  ruler: boolean | GaugeRulerOptions | undefined
): GaugeRulerOptions | null {
  if (!ruler) {
    return null;
  }
  return ruler === true ? {} : ruler;
}

export function GaugeNeedle({
  cx,
  cy,
  reach,
  startAngle,
  endAngle,
  progress,
  options,
}: {
  cx: number;
  cy: number;
  /** Distance from center to needle tip */
  reach: number;
  startAngle: number;
  endAngle: number;
  progress: MotionValue<number>;
  options: GaugeNeedleOptions;
}) {
  const {
    variant = "gradient",
    color = "var(--foreground)",
    width = NEEDLE_DEFAULT_WIDTH[variant],
    length = 0.55,
    pivot = false,
  } = options;
  const gradientId = `gauge-needle-${useId().replace(/:/g, "")}`;
  const groupRef = useRef<SVGGElement>(null);

  const angleAt = (p: number) => startAngle + p * (endAngle - startAngle);
  const transformAt = (p: number) =>
    `translate(${cx} ${cy}) rotate(${angleAt(p)})`;

  useMotionValueApply(progress, (p) => {
    groupRef.current?.setAttribute("transform", transformAt(p));
  });

  const tip = reach;
  const base = reach * (1 - Math.min(1, Math.max(0.05, length)));
  const span = tip - base;
  const half = width / 2;

  let shape: ReactNode;
  switch (variant) {
    case "line":
      shape = (
        <line
          stroke={color}
          strokeLinecap="round"
          strokeWidth={width}
          // Keep the round caps inside [base, tip] so the tip never overruns.
          x1={base + half}
          x2={tip - half}
          y1={0}
          y2={0}
        />
      );
      break;
    case "gradient":
      shape = (
        <>
          <defs>
            <linearGradient
              gradientUnits="userSpaceOnUse"
              id={gradientId}
              x1={base}
              x2={tip}
              y1={0}
              y2={0}
            >
              <stop offset="0%" stopColor={color} stopOpacity={0} />
              <stop offset="70%" stopColor={color} stopOpacity={0.7} />
              <stop offset="100%" stopColor={color} stopOpacity={1} />
            </linearGradient>
          </defs>
          {/* Tapered body so the fade reads as light, not a cut-off stroke */}
          <path
            d={`M ${base} ${-half * 0.35} L ${tip - half} ${-half} A ${half} ${half} 0 0 1 ${tip - half} ${half} L ${base} ${half * 0.35} Z`}
            fill={`url(#${gradientId})`}
          />
        </>
      );
      break;
    case "triangle":
      shape = (
        <polygon
          fill={color}
          points={`${base},${-half} ${tip},0 ${base},${half}`}
          stroke={color}
          strokeLinejoin="round"
          strokeWidth={1.25}
        />
      );
      break;
    case "polygon": {
      const shoulder = base + span * 0.22;
      shape = (
        <polygon
          fill={color}
          points={`${base},0 ${shoulder},${-half} ${tip},0 ${shoulder},${half}`}
          stroke={color}
          strokeLinejoin="round"
          strokeWidth={1.25}
        />
      );
      break;
    }
    default:
      shape = null;
  }

  return (
    <g>
      <g ref={groupRef} transform={transformAt(progress.get())}>
        {shape}
      </g>
      {pivot ? (
        <>
          <circle cx={cx} cy={cy} fill={color} r={Math.max(4, width * 0.9)} />
          <circle
            cx={cx}
            cy={cy}
            fill="var(--background)"
            r={Math.max(1.5, width * 0.35)}
          />
        </>
      ) : null}
    </g>
  );
}

"use client";

import type { MotionValue } from "motion/react";
import { useId, useRef } from "react";
import { clamp01, useMotionValueApply } from "./gauge-dial";

/* -------------------------------------------------------------------------- */
/*                                  Geometry                                  */
/* -------------------------------------------------------------------------- */

const MIN_SWEEP = 0.01;
const MAX_SWEEP = 359.99;

function polar(cx: number, cy: number, r: number, deg: number) {
  const rad = (deg * Math.PI) / 180;
  return [cx + Math.cos(rad) * r, cy + Math.sin(rad) * r] as const;
}

/** Centerline arc from `a0` to `a1` (degrees, clockwise). Empty when degenerate. */
export function arcStrokePath(
  cx: number,
  cy: number,
  r: number,
  a0: number,
  a1: number
): string {
  const sweep = Math.min(MAX_SWEEP, a1 - a0);
  if (sweep < MIN_SWEEP || r <= 0) {
    return "";
  }
  const [x0, y0] = polar(cx, cy, r, a0);
  const [x1, y1] = polar(cx, cy, r, a0 + sweep);
  const large = sweep > 180 ? 1 : 0;
  return `M ${x0} ${y0} A ${r} ${r} 0 ${large} 1 ${x1} ${y1}`;
}

/** Filled ring segment between radii `r0` (inner, may be 0) and `r1`. */
export function annularSectorPath(
  cx: number,
  cy: number,
  r0: number,
  r1: number,
  a0: number,
  a1: number
): string {
  const sweep = Math.min(MAX_SWEEP, a1 - a0);
  if (sweep < MIN_SWEEP) {
    return "";
  }
  const end = a0 + sweep;
  const large = sweep > 180 ? 1 : 0;
  const [ox0, oy0] = polar(cx, cy, r1, a0);
  const [ox1, oy1] = polar(cx, cy, r1, end);
  if (r0 <= 0.5) {
    return `M ${cx} ${cy} L ${ox0} ${oy0} A ${r1} ${r1} 0 ${large} 1 ${ox1} ${oy1} Z`;
  }
  const [ix1, iy1] = polar(cx, cy, r0, end);
  const [ix0, iy0] = polar(cx, cy, r0, a0);
  return `M ${ox0} ${oy0} A ${r1} ${r1} 0 ${large} 1 ${ox1} ${oy1} L ${ix1} ${iy1} A ${r0} ${r0} 0 ${large} 0 ${ix0} ${iy0} Z`;
}

/* -------------------------------------------------------------------------- */
/*                                    Zones                                   */
/* -------------------------------------------------------------------------- */

export interface GaugeZone {
  /** Start of the zone, 0–100 */
  from: number;
  /** End of the zone, 0–100 */
  to: number;
  color: string;
}

/**
 * `band` — thin arc ringing the track · `fill` — the fill takes the zone
 * colour where it overlaps · `both`.
 */
export type GaugeZoneDisplay = "band" | "fill" | "both";

export function zoneColorAt(
  zones: readonly GaugeZone[] | undefined,
  t: number
): string | undefined {
  if (!zones) {
    return;
  }
  const pct = t * 100;
  for (let i = zones.length - 1; i >= 0; i--) {
    const z = zones[i];
    if (z && pct >= z.from && pct <= z.to) {
      return z.color;
    }
  }
}

export const ZONE_BAND_WIDTH = 0.014;

export function GaugeZoneBands({
  cx,
  cy,
  radius,
  size,
  startAngle,
  endAngle,
  zones,
  opacity = 0.9,
}: {
  cx: number;
  cy: number;
  radius: number;
  size: number;
  startAngle: number;
  endAngle: number;
  zones: readonly GaugeZone[];
  opacity?: number;
}) {
  const sweep = endAngle - startAngle;
  return (
    <g>
      {zones.map((z) => (
        <path
          d={arcStrokePath(
            cx,
            cy,
            radius,
            startAngle + clamp01(z.from / 100) * sweep,
            startAngle + clamp01(z.to / 100) * sweep
          )}
          fill="none"
          key={`${z.from}-${z.to}-${z.color}`}
          stroke={z.color}
          strokeOpacity={opacity}
          strokeWidth={size * ZONE_BAND_WIDTH}
        />
      ))}
    </g>
  );
}

/* -------------------------------------------------------------------------- */
/*                                  Solid arc                                 */
/* -------------------------------------------------------------------------- */

export function GaugeSolidArc({
  cx,
  cy,
  radius,
  thickness,
  startAngle,
  endAngle,
  progress,
  trackColor,
  trackOpacity,
  fill,
  fillOpacity,
  zones,
  glowFilterId,
}: {
  cx: number;
  cy: number;
  /** Centerline radius */
  radius: number;
  thickness: number;
  startAngle: number;
  endAngle: number;
  progress: MotionValue<number>;
  trackColor: string;
  trackOpacity: number;
  fill: string;
  fillOpacity: number;
  /** Zones painted over the fill (`zoneDisplay` fill / both) */
  zones?: readonly GaugeZone[];
  glowFilterId?: string;
}) {
  const sweep = endAngle - startAngle;
  const fillRef = useRef<SVGPathElement>(null);
  const zoneRefs = useRef<(SVGPathElement | null)[]>([]);

  const fillD = (p: number) =>
    arcStrokePath(cx, cy, radius, startAngle, startAngle + p * sweep);
  const zoneD = (z: GaugeZone, p: number) => {
    const from = clamp01(z.from / 100);
    const to = Math.min(clamp01(z.to / 100), p);
    return to > from
      ? arcStrokePath(
          cx,
          cy,
          radius,
          startAngle + from * sweep,
          startAngle + to * sweep
        )
      : "";
  };

  useMotionValueApply(progress, (p) => {
    fillRef.current?.setAttribute("d", fillD(p));
    zones?.forEach((z, i) => {
      zoneRefs.current[i]?.setAttribute("d", zoneD(z, p));
    });
  });

  const p0 = progress.get();
  return (
    <g>
      <path
        d={arcStrokePath(cx, cy, radius, startAngle, endAngle)}
        fill="none"
        stroke={trackColor}
        strokeLinecap="round"
        strokeOpacity={trackOpacity}
        strokeWidth={thickness}
      />
      <g filter={glowFilterId ? `url(#${glowFilterId})` : undefined}>
        <path
          d={fillD(p0)}
          fill="none"
          ref={fillRef}
          stroke={fill}
          strokeLinecap="round"
          strokeOpacity={fillOpacity}
          strokeWidth={thickness}
        />
        {zones?.map((z, i) => (
          <path
            d={zoneD(z, p0)}
            fill="none"
            key={`${z.from}-${z.to}-${z.color}`}
            ref={(el) => {
              zoneRefs.current[i] = el;
            }}
            stroke={z.color}
            strokeOpacity={fillOpacity}
            strokeWidth={thickness}
          />
        ))}
      </g>
    </g>
  );
}

/* -------------------------------------------------------------------------- */
/*                                   Sector                                   */
/* -------------------------------------------------------------------------- */

export interface GaugeSectorOptions {
  /**
   * `conic` — brightens toward the leading edge · `radial` — brightens toward
   * the rim · `none` — flat `color` (use a `url(#pattern)` for patterns).
   * Default `conic`.
   */
  gradient?: "conic" | "radial" | "none";
  /** Default `var(--chart-1)` */
  color?: string;
  /** Peak opacity. Default 0.85 */
  opacity?: number;
  /** Inner radius as a fraction of the sector's outer radius. Default 0 */
  innerRadius?: number;
}

export function resolveSectorOptions(
  sector: boolean | GaugeSectorOptions | undefined
): GaugeSectorOptions | null {
  if (!sector) {
    return null;
  }
  return sector === true ? {} : sector;
}

/** SVG sector for `radial` and `none` gradients (patterns welcome). */
export function GaugeSector({
  cx,
  cy,
  radius,
  startAngle,
  endAngle,
  progress,
  options,
}: {
  cx: number;
  cy: number;
  radius: number;
  startAngle: number;
  endAngle: number;
  progress: MotionValue<number>;
  options: GaugeSectorOptions;
}) {
  const {
    gradient = "conic",
    color = "var(--chart-1)",
    opacity = 0.85,
    innerRadius = 0,
  } = options;
  const gradientId = `gauge-sector-${useId().replace(/:/g, "")}`;
  const ref = useRef<SVGPathElement>(null);
  const r0 = radius * clamp01(innerRadius);
  const sweep = endAngle - startAngle;
  const d = (p: number) =>
    annularSectorPath(cx, cy, r0, radius, startAngle, startAngle + p * sweep);

  useMotionValueApply(progress, (p) => {
    ref.current?.setAttribute("d", d(p));
  });

  const isRadial = gradient === "radial";
  return (
    <g>
      {isRadial ? (
        <defs>
          <radialGradient
            cx={cx}
            cy={cy}
            gradientUnits="userSpaceOnUse"
            id={gradientId}
            r={radius}
          >
            <stop offset="0%" stopColor={color} stopOpacity={0} />
            <stop
              offset={`${Math.round((r0 / radius) * 100)}%`}
              stopColor={color}
              stopOpacity={0.04}
            />
            <stop offset="100%" stopColor={color} stopOpacity={opacity} />
          </radialGradient>
        </defs>
      ) : null}
      <path
        d={d(progress.get())}
        fill={isRadial ? `url(#${gradientId})` : color}
        fillOpacity={isRadial ? 1 : opacity}
        ref={ref}
      />
    </g>
  );
}

/**
 * Conic sector — SVG has no conic gradient, so this is an HTML layer behind
 * the SVG with a CSS `conic-gradient`, clipped to the sector path each frame.
 */
export function GaugeConicSector({
  cx,
  cy,
  radius,
  startAngle,
  endAngle,
  progress,
  options,
}: {
  cx: number;
  cy: number;
  radius: number;
  startAngle: number;
  endAngle: number;
  progress: MotionValue<number>;
  options: GaugeSectorOptions;
}) {
  const { color = "var(--chart-1)", opacity = 0.85, innerRadius = 0 } = options;
  const ref = useRef<HTMLDivElement>(null);
  const r0 = radius * clamp01(innerRadius);
  const sweep = endAngle - startAngle;

  // CSS conic 0deg points up; SVG 0deg points right.
  const style = (p: number) => {
    const deg = p * sweep;
    const path = annularSectorPath(
      cx,
      cy,
      r0,
      radius,
      startAngle,
      startAngle + deg
    );
    return {
      background: `conic-gradient(from ${startAngle + 90}deg at ${cx}px ${cy}px, transparent 0deg, ${color} ${Math.max(deg, 0.01)}deg, transparent ${Math.max(deg, 0.01)}deg)`,
      clipPath: path ? `path("${path}")` : "inset(50%)",
    };
  };

  useMotionValueApply(progress, (p) => {
    const el = ref.current;
    if (!el) {
      return;
    }
    const next = style(p);
    el.style.background = next.background;
    el.style.clipPath = next.clipPath;
  });

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute inset-0"
      ref={ref}
      style={{ ...style(progress.get()), opacity }}
    />
  );
}

/* -------------------------------------------------------------------------- */
/*                                Progress ring                               */
/* -------------------------------------------------------------------------- */

export interface GaugeProgressRingOptions {
  /** Default `var(--chart-1)` */
  color?: string;
  /** Remainder colour. Default `var(--muted-foreground)` */
  trackColor?: string;
  /** Remainder opacity. Default 0.35 */
  trackOpacity?: number;
  /** Stroke width as a fraction of size. Default 0.01 */
  width?: number;
  /** Gap from the track as a fraction of size. Default 0.022 */
  gap?: number;
}

export function resolveProgressRingOptions(
  ring: boolean | GaugeProgressRingOptions | undefined
): GaugeProgressRingOptions | null {
  if (!ring) {
    return null;
  }
  return ring === true ? {} : ring;
}

export function progressRingExtent(
  options: GaugeProgressRingOptions,
  size: number
) {
  return size * ((options.gap ?? 0.022) + (options.width ?? 0.01));
}

export function GaugeProgressRing({
  cx,
  cy,
  radius,
  size,
  startAngle,
  endAngle,
  progress,
  options,
  glowFilterId,
}: {
  cx: number;
  cy: number;
  /** Centerline radius */
  radius: number;
  size: number;
  startAngle: number;
  endAngle: number;
  progress: MotionValue<number>;
  options: GaugeProgressRingOptions;
  glowFilterId?: string;
}) {
  const {
    color = "var(--chart-1)",
    trackColor = "var(--muted-foreground)",
    trackOpacity = 0.35,
    width = 0.01,
  } = options;
  const activeRef = useRef<SVGPathElement>(null);
  const restRef = useRef<SVGPathElement>(null);
  const sweep = endAngle - startAngle;
  const at = (p: number) => startAngle + p * sweep;

  useMotionValueApply(progress, (p) => {
    activeRef.current?.setAttribute(
      "d",
      arcStrokePath(cx, cy, radius, startAngle, at(p))
    );
    restRef.current?.setAttribute(
      "d",
      arcStrokePath(cx, cy, radius, at(p), endAngle)
    );
  });

  const p0 = progress.get();
  const strokeWidth = Math.max(1, size * width);
  return (
    <g>
      <path
        d={arcStrokePath(cx, cy, radius, at(p0), endAngle)}
        fill="none"
        ref={restRef}
        stroke={trackColor}
        strokeOpacity={trackOpacity}
        strokeWidth={strokeWidth}
      />
      <path
        d={arcStrokePath(cx, cy, radius, startAngle, at(p0))}
        fill="none"
        filter={glowFilterId ? `url(#${glowFilterId})` : undefined}
        ref={activeRef}
        stroke={color}
        strokeWidth={strokeWidth}
      />
    </g>
  );
}

/* -------------------------------------------------------------------------- */
/*                                Progress dots                               */
/* -------------------------------------------------------------------------- */

export interface GaugeDotsOptions {
  /** Concentric rings of dots. Default 5 */
  rings?: number;
  /** Distance between dots (and rings) as a fraction of size. Default 0.03 */
  spacing?: number;
  /** Dot radius in px. Default 1.6 */
  radius?: number;
  /** Default `var(--chart-1)` */
  color?: string;
  /** Opacity of dots past the value. Default 0.12 */
  dimOpacity?: number;
  /** Opacity of dots up to the value. Default 0.9 */
  litOpacity?: number;
  /** Fade rings toward the center. Default true */
  fadeInward?: boolean;
}

export function resolveDotsOptions(
  dots: boolean | GaugeDotsOptions | undefined
): GaugeDotsOptions | null {
  if (!dots) {
    return null;
  }
  return dots === true ? {} : dots;
}

export function GaugeDots({
  cx,
  cy,
  outerRadius,
  size,
  startAngle,
  endAngle,
  progress,
  options,
}: {
  cx: number;
  cy: number;
  /** Radius of the outermost ring */
  outerRadius: number;
  size: number;
  startAngle: number;
  endAngle: number;
  progress: MotionValue<number>;
  options: GaugeDotsOptions;
}) {
  const {
    rings = 5,
    spacing = 0.03,
    radius = 1.6,
    color = "var(--chart-1)",
    dimOpacity = 0.12,
    litOpacity = 0.9,
    fadeInward = true,
  } = options;
  const step = Math.max(4, size * spacing);
  const sweep = endAngle - startAngle;
  const sweepRad = (sweep * Math.PI) / 180;
  const ringCount = Math.max(1, Math.round(rings));

  const dots: { x: number; y: number; t: number; weight: number }[] = [];
  for (let k = 0; k < ringCount; k++) {
    const r = outerRadius - k * step;
    if (r <= step) {
      break;
    }
    const count = Math.max(2, Math.round((sweepRad * r) / step));
    const weight = fadeInward ? 1 - (k / ringCount) * 0.6 : 1;
    for (let i = 0; i <= count; i++) {
      const t = i / count;
      const [x, y] = polar(cx, cy, r, startAngle + t * sweep);
      dots.push({ x, y, t, weight });
    }
  }

  const refs = useRef<(SVGCircleElement | null)[]>([]);
  const opacityAt = (p: number, t: number, weight: number) => {
    const lit = clamp01((p - t) * 60 + 1);
    return (dimOpacity + (litOpacity - dimOpacity) * lit) * weight;
  };

  useMotionValueApply(progress, (p) => {
    dots.forEach((dot, i) => {
      refs.current[i]?.setAttribute(
        "fill-opacity",
        String(opacityAt(p, dot.t, dot.weight))
      );
    });
  });

  const p0 = progress.get();
  return (
    <g>
      {dots.map((dot, i) => (
        <circle
          cx={dot.x}
          cy={dot.y}
          fill={color}
          fillOpacity={opacityAt(p0, dot.t, dot.weight)}
          key={i}
          r={radius}
          ref={(el) => {
            refs.current[i] = el;
          }}
        />
      ))}
    </g>
  );
}

/* -------------------------------------------------------------------------- */
/*                              Disc + glow filter                            */
/* -------------------------------------------------------------------------- */

export interface GaugeCenterDiscOptions {
  /** Radius as a fraction of size. Default 0.19 */
  radius?: number;
  /** Default `var(--background)` */
  fill?: string;
  /** Default `var(--foreground)` */
  stroke?: string;
  strokeOpacity?: number;
  /** Ring width in px. Default 3 */
  strokeWidth?: number;
}

export function resolveCenterDiscOptions(
  disc: boolean | GaugeCenterDiscOptions | undefined
): GaugeCenterDiscOptions | null {
  if (!disc) {
    return null;
  }
  return disc === true ? {} : disc;
}

export function GaugeCenterDisc({
  cx,
  cy,
  size,
  options,
}: {
  cx: number;
  cy: number;
  size: number;
  options: GaugeCenterDiscOptions;
}) {
  const {
    radius = 0.19,
    fill = "var(--background)",
    stroke = "var(--foreground)",
    strokeOpacity = 0.75,
    strokeWidth = 3,
  } = options;
  return (
    <circle
      cx={cx}
      cy={cy}
      fill={fill}
      r={size * radius}
      stroke={stroke}
      strokeOpacity={strokeOpacity}
      strokeWidth={strokeWidth}
    />
  );
}

export interface GaugeGlowOptions {
  /** Blur radius in px. Default 6 */
  blur?: number;
  /** Glow strength 0–1. Default 0.8 */
  intensity?: number;
}

export function resolveGlowOptions(
  glow: boolean | GaugeGlowOptions | undefined
): GaugeGlowOptions | null {
  if (!glow) {
    return null;
  }
  return glow === true ? {} : glow;
}

export function GaugeGlowFilter({
  id,
  options,
}: {
  id: string;
  options: GaugeGlowOptions;
}) {
  const { blur = 6, intensity = 0.8 } = options;
  return (
    <filter height="200%" id={id} width="200%" x="-50%" y="-50%">
      <feGaussianBlur in="SourceGraphic" result="blur" stdDeviation={blur} />
      <feComponentTransfer in="blur" result="glow">
        <feFuncA slope={intensity} type="linear" />
      </feComponentTransfer>
      <feMerge>
        <feMergeNode in="glow" />
        <feMergeNode in="SourceGraphic" />
      </feMerge>
    </filter>
  );
}

/**
 * Fluid typography for pie / ring / gauge center labels.
 *
 * Uses CSS container query units (`cqw`) so values scale with the center
 * hole — not the viewport — which keeps stat text readable on small charts.
 */
export const chartCenterContainerClassName =
  "@container/chart-center size-full min-w-0";

